/*
	Created by: Elodie
	Date: 20200415
	Task: Reduce PT of Sexy Gaming and BBIN
	DB: DBCUST/CustDB

	MaxRangeS3 = l4 - s3 - MAX(m2+a2)
	IncreaseValue = @PT_New - s3 - MIN(m2+a2)
	IncreaseS3 = @PT_New - s3 - MAX(m2+a2)

	IF IncreaseValue > 0
		IF IncreaseS3 > 0
			IF IncreaseS3 <= MaxRangeS3 THEN s3 = s3 + IncreaseS3
			IF IncreaseS3 > MaxRangeS3 THEN s3 = s3 + MaxRangeS3, m2 = @PT_New - s3_new - a2
		IF IncreaseS3 <= 0 AND a2 + s3 + m2 < @PT_New THEN m2 = @MinPT_New - s3 - a2
*/
ALTER PROCEDURE dbo.Acc_DynamicCustSetting3rd_09
	@srecommend INT,
	@Target VARCHAR(20)
AS
BEGIN
	SET NOCOUNT ON
	IF (@target = 'REPLICATED' AND @@SERVERNAME IN ('DBCUST','SITDBCUST','DB233','DB230\SQLSERVER2008R2')) RETURN	-- run at all replicated servers
	IF (@target = 'DBCUST' AND @@SERVERNAME NOT IN ('DBCUST','SITDBCUST','DB233','DB230\SQLSERVER2008R2')) RETURN -- run at dbcust only

	IF dbo.f_CheckRepTable('CustInfo') = 0 RETURN
	IF dbo.f_CheckRepTable('Customer') = 0 RETURN
	IF dbo.f_CheckRepTable('CustPTSetting3rd_Agent') = 0 RETURN
	IF dbo.f_CheckRepTable('CustPTSetting3rd_Member') = 0 RETURN
	IF dbo.f_CheckRepTable('CustPTGroupSetting3rd_Member') = 0 RETURN	

	DECLARE @PT_New TINYINT = 70

	CREATE TABLE #SuperList (CustId INT, sporttype SMALLINT, bettype SMALLINT, IsLive BIT, L4 TINYINT)
	CREATE TABLE #MasterList (CustId INT, srecommend INT, sporttype SMALLINT, bettype SMALLINT, IsLive BIT, S3 INT, MaxM2A2 INT, MinM2A2 INT, MaxRangeS3 INT, IncreaseValue INT, IncreaseS3 INT, S3_New INT, SuperPT_XML XML)
	CREATE TABLE #AgentList (CustId INT, mrecommend INT, sporttype SMALLINT, bettype SMALLINT, IsLive BIT, A2 INT, M2_New INT, MasterPT_XML XML)

	INSERT INTO #SuperList (CustId, sporttype, bettype, IsLive, L4)
	SELECT cs.custid, cs.sporttype, cs.bettype, cs.isLive, cs.MaxPT 
	FROM dbo.CustPTSetting3rd_Agent cs WITH (NOLOCK)
	WHERE cs.CustID = @srecommend
		AND cs.SportType IN (243, 241)

	INSERT INTO #MasterList (CustId, srecommend, sporttype, bettype, IsLive, S3, MaxM2A2, MinM2A2)
	SELECT c.custid, c.srecommend, mpt.sporttype, mpt.bettype, mpt.isLive, mpt.SuperPT, MAX(apt.MasterPT+apt.AgentPT), MIN(apt.MasterPT+apt.AgentPT)
	FROM vw_Customer c WITH (NOLOCK) 
		INNER JOIN vw_Customer a WITH (NOLOCK) ON a.mrecommend = c.custid
		INNER JOIN #SuperList s WITH (NOLOCK) ON c.srecommend = s.custid
		INNER JOIN dbo.CustPTSetting3rd_Agent apt WITH (NOLOCK) ON apt.CustID = a.custid
		INNER JOIN dbo.CustPTSetting3rd_Agent mpt WITH (NOLOCK) ON mpt.CustID = c.custid AND mpt.SportType = apt.SportType AND mpt.BetType = apt.BetType AND mpt.isLive = apt.isLive
	WHERE c.roleid = 3 AND a.roleid = 2
		AND apt.SportType IN (243, 241)
	GROUP BY c.custid, c.srecommend, mpt.sporttype, mpt.bettype, mpt.isLive, mpt.SuperPT

	UPDATE ml 
	SET MaxRangeS3 = sl.L4 - ml.S3 - MaxM2A2,
		IncreaseValue = @PT_New - ml.S3 - MinM2A2,
		IncreaseS3 = @PT_New - ml.S3 - MaxM2A2
	FROM #MasterList ml
		INNER JOIN #SuperList sl ON sl.CustId = ml.srecommend AND sl.sporttype = ml.sporttype AND sl.bettype = ml.bettype AND sl.IsLive = ml.IsLive

	UPDATE ml 
	SET ml.S3_New = CASE	WHEN IncreaseValue > 0 AND IncreaseS3 > 0 AND IncreaseS3 <= MaxRangeS3 THEN S3 + ml.IncreaseS3
							WHEN IncreaseValue > 0 AND IncreaseS3 > 0 AND IncreaseS3 > MaxRangeS3 THEN S3 + ml.MaxRangeS3 ELSE ml.S3 END
	FROM #MasterList ml

	INSERT INTO #AgentList (CustId, mrecommend, sporttype, bettype, IsLive, A2, M2_New)
	SELECT a.custid, a.mrecommend, apt.sporttype, apt.bettype, apt.isLive, apt.AgentPT,
		CASE	WHEN ml.IncreaseS3 > 0 AND IncreaseS3 < IncreaseValue THEN @PT_New - ml.S3_New - apt.AgentPT
				WHEN ml.IncreaseS3 <= 0 AND apt.AgentPT + ml.S3_New + apt.MasterPT < @PT_New THEN @PT_New - ml.S3 - apt.AgentPT END
	FROM custinfo a
		INNER JOIN dbo.CustPTSetting3rd_Agent apt WITH (NOLOCK) ON apt.CustID = a.custid
		INNER JOIN #MasterList ml ON ml.CustId = a.mrecommend AND apt.sporttype = ml.sporttype AND apt.bettype = ml.bettype AND apt.isLive = ml.IsLive
	WHERE a.roleid = 2 AND
		IncreaseValue > 0 AND
		((IncreaseS3 > 0 AND IncreaseS3 < IncreaseValue) OR (ml.IncreaseS3 <= 0 AND apt.AgentPT + ml.S3_New + apt.MasterPT < @PT_New))	

	SELECT * FROM #SuperList --WHERE custid = 35555477
	SELECT * FROM #MasterList --WHERE srecommend = 35555477
	SELECT * FROM #AgentList --WHERE mrecommend = 35555506

	------------------UPDATE-------------------------------------------------------------------
	--Update MinPT of Super
	UPDATE cs
	SET cs.SuperPT = @PT_New,
		cs.MasterPT = @PT_New,
		cs.AgentPT = @PT_New
	FROM dbo.CustPTSetting3rd_Agent cs WITH (ROWLOCK)
	WHERE cs.CustID = @srecommend
		AND cs.SportType IN (241, 243)

	--Update s3 of Master
	UPDATE cs
	SET cs.SuperPT = ml.S3_New
	FROM dbo.CustPTSetting3rd_Agent cs WITH (ROWLOCK) 
		INNER JOIN #MasterList ml ON ml.CustId = cs.CustId AND ml.sporttype = cs.SportType AND ml.bettype = cs.BetType AND ml.IsLive = cs.IsLive

	--Update s3 of Member
	UPDATE cs
	SET cs.SuperPT =ml.S3_New
	FROM dbo.CustPTSetting3rd_Member cs WITH (ROWLOCK) 
		INNER JOIN dbo.custInfo ci WITH (NOLOCK) ON ci.custid = cs.CustID
		INNER JOIN #MasterList ml ON ml.CustId = ci.mrecommend AND ml.sporttype = cs.SportType AND ml.bettype = cs.BetType AND ml.IsLive = cs.IsLive
	WHERE ci.roleid = 1

	UPDATE cs
	SET cs.SuperPT =ml.S3_New
	FROM dbo.CustPTGroupSetting3rd_Member cs WITH (ROWLOCK) 
		INNER JOIN dbo.custInfo ci WITH (NOLOCK) ON ci.custid = cs.AgentID
		INNER JOIN #MasterList ml ON ml.CustId = ci.mrecommend AND ml.sporttype = cs.SportType AND ml.bettype = cs.BetType AND ml.IsLive = cs.IsLive
	WHERE ci.roleid = 2

	--Update m2 of Agent
	UPDATE cs
	SET cs.MasterPT = M2_New
	FROM dbo.CustPTSetting3rd_Agent cs WITH (ROWLOCK) 
		INNER JOIN #AgentList al ON al.CustId = cs.CustId AND al.sporttype = cs.SportType AND al.bettype = cs.BetType AND al.IsLive = cs.IsLive

	--Update m2 of Member
	UPDATE cs
	SET cs.MasterPT = al.M2_New
	FROM dbo.CustPTGroupSetting3rd_Member cs WITH (ROWLOCK) 
		INNER JOIN #AgentList al ON al.CustId = cs.AgentId AND al.sporttype = cs.SportType AND al.bettype = cs.BetType AND al.IsLive = cs.IsLive

	UPDATE cs
	SET cs.MasterPT = al.M2_New
	FROM dbo.CustPTSetting3rd_Member cs WITH (ROWLOCK) 
		INNER JOIN dbo.custInfo ci WITH (NOLOCK) ON ci.custid = cs.CustID
		INNER JOIN #AgentList al ON al.CustId = ci.recommend AND al.sporttype = cs.SportType AND al.bettype = cs.BetType AND al.IsLive = cs.IsLive
	WHERE ci.roleid = 1

	DROP TABLE #SuperList
	DROP TABLE #MasterList
	DROP TABLE #AgentList

END
GO
-- END STEP 1: DEPLOY THIS SP @DBCUST.CustDB --------
------------------------------------------------------	

